import unittest

from solucao import pedaco


class TestFatiarOTexto(unittest.TestCase):
    def test_pega_do_meio(self):
        """pedaco devolve o trecho do meio do texto"""
        self.assertEqual(pedaco("banana", 2, 5), "nan")

    def test_pega_do_comeco(self):
        """pedaco devolve o trecho do comeco do texto"""
        self.assertEqual(pedaco("banana", 0, 3), "ban")

    def test_pega_uma_letra_so(self):
        """pedaco devolve uma letra quando o trecho tem tamanho um"""
        self.assertEqual(pedaco("ola", 1, 2), "l")

    def test_ate_o_fim_sem_incluir_o_fim(self):
        """pedaco devolve ate antes do fim pedido"""
        self.assertEqual(pedaco("banana", 1, 6), "anana")
